import{_ as s,o as e,c as n,a6 as t}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"服务端推送","description":"PUSH_PROMISE 机制、它为什么失败，以及 103 Early Hints 这个替代方案。","frontmatter":{"title":"服务端推送","description":"PUSH_PROMISE 机制、它为什么失败，以及 103 Early Hints 这个替代方案。","source":"https://daiw.org/manual/http2-3/h2-server-push"},"headers":[],"relativePath":"manual/computer-programming/http2-3/h2-server-push.md","filePath":"manual/computer-programming/http2-3/h2-server-push.md"}'),r={name:"manual/computer-programming/http2-3/h2-server-push.md"};function i(l,a,p,o,d,h){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="服务端推送" tabindex="-1">服务端推送 <a class="header-anchor" href="#服务端推送" aria-label="Permalink to &quot;服务端推送&quot;">​</a></h1><p>PUSH_PROMISE 机制、它为什么失败，以及 103 Early Hints 这个替代方案。</p><p>服务端推送是 HTTP/2 早期备受关注、但最终<strong>被实践否决</strong>的代表性特性（另一个是 RFC 7540 的依赖优先级树）。这一篇讲清它怎么工作、为什么废了。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>想法：服务端知道客户端拿了 <code>index.html</code> 就一定会来要 <code>style.css</code>，那不如<strong>主动推过去</strong>，省一个 RTT。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端 → HEADERS(流1): GET /index.html</span></span>
<span class="line"><span>服务端 → PUSH_PROMISE(流1, 承诺流2): GET /style.css   ← 预告</span></span>
<span class="line"><span>服务端 → HEADERS(流1) + DATA(流1): index.html 的响应</span></span>
<span class="line"><span>服务端 → HEADERS(流2) + DATA(流2): style.css 的响应   ← 推送内容</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="push-promise" tabindex="-1">PUSH_PROMISE <a class="header-anchor" href="#push-promise" aria-label="Permalink to &quot;PUSH_PROMISE&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-+-------------------------------------------------------------+</span></span>
<span class="line"><span>|R|                Promised Stream ID (31)                      |</span></span>
<span class="line"><span>+-+-------------------------------------------------------------+</span></span>
<span class="line"><span>|                   Header Block Fragment (*)                   |</span></span>
<span class="line"><span>+---------------------------------------------------------------+</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>规则：</p><ul><li><strong>MUST</strong> 在其所关联的流上发送（不是在被承诺的流上）。</li><li>Promised Stream ID <strong>MUST 是偶数</strong>（服务端发起）且单调递增。</li><li>携带的字段块是<strong>服务端替客户端构造的请求头</strong>——即「你本来会发的那个请求」。</li><li>该请求 <strong>MUST 是安全且幂等</strong>的（实际上只有 <code>GET</code>/<code>HEAD</code> 合理），且 <strong>MUST NOT</strong> 带请求体。</li><li>被承诺的流进入 <code>reserved (remote)</code> 状态，客户端此时可用 <code>RST_STREAM</code>（<code>CANCEL</code>）拒绝。</li></ul><h3 id="关闭推送" tabindex="-1">关闭推送 <a class="header-anchor" href="#关闭推送" aria-label="Permalink to &quot;关闭推送&quot;">​</a></h3><p><code>SETTINGS_ENABLE_PUSH = 0</code> 表示不接受推送。服务端在收到该设置后仍发 <code>PUSH_PROMISE</code> → <code>PROTOCOL_ERROR</code>。</p><p>客户端<strong>不能</strong>在收到推送前预先知道要推什么，只能整体开关或逐个 <code>RST_STREAM</code>。</p><h2 id="为什么失败" tabindex="-1">为什么失败 <a class="header-anchor" href="#为什么失败" aria-label="Permalink to &quot;为什么失败&quot;">​</a></h2><p>推送在 2015 年被寄予厚望，2022 年后主流浏览器全部移除支持（Chrome 106 起默认关闭并最终删除）。原因逐条：</p><h3 id="_1-服务端不知道客户端缓存里有什么" tabindex="-1">1. 服务端不知道客户端缓存里有什么 <a class="header-anchor" href="#_1-服务端不知道客户端缓存里有什么" aria-label="Permalink to &quot;1. 服务端不知道客户端缓存里有什么&quot;">​</a></h3><p>这是<strong>根本性缺陷</strong>。服务端推送 <code>style.css</code> 时，客户端很可能早已缓存了它。结果是白白浪费带宽——而且推送发生在客户端有机会说「我有了」之前。</p><p>规范提供的补救（<code>RST_STREAM</code> 取消）来得太晚：取消到达服务端时，数据往往已经在路上或已发完。曾有过 <strong>Cache Digest</strong> 提案（客户端把缓存摘要发给服务端），因复杂度与隐私问题被放弃。</p><h3 id="_2-与流量控制争抢" tabindex="-1">2. 与流量控制争抢 <a class="header-anchor" href="#_2-与流量控制争抢" aria-label="Permalink to &quot;2. 与流量控制争抢&quot;">​</a></h3><p>推送的流与真正被请求的资源<strong>共享同一个<a href="/Front2Full/manual/computer-programming/http2-3/h2-flow-control">连接窗口</a></strong>。推送一个不需要的大文件，会直接拖慢客户端真正在等的 HTML——<strong>负优化</strong>。</p><h3 id="_3-优先级难以调对" tabindex="-1">3. 优先级难以调对 <a class="header-anchor" href="#_3-优先级难以调对" aria-label="Permalink to &quot;3. 优先级难以调对&quot;">​</a></h3><p>推送的资源该排在哪个优先级？服务端很难判断。推早了挤占关键资源带宽，推晚了失去意义。而 h2 的<a href="/Front2Full/manual/computer-programming/http2-3/h2-settings-priority">优先级树本身也已废弃</a>。</p><h3 id="_4-实测收益微弱" tabindex="-1">4. 实测收益微弱 <a class="header-anchor" href="#_4-实测收益微弱" aria-label="Permalink to &quot;4. 实测收益微弱&quot;">​</a></h3><p>Chrome 团队 2020–2021 的大规模实测结论：推送对首屏指标的改善<strong>中位数接近零</strong>，且有相当比例的站点因误用而<strong>变慢</strong>。同时它显著增加了服务端实现与运维复杂度。</p><h3 id="_5-有更好的替代品" tabindex="-1">5. 有更好的替代品 <a class="header-anchor" href="#_5-有更好的替代品" aria-label="Permalink to &quot;5. 有更好的替代品&quot;">​</a></h3><p>见下。</p><h2 id="替代方案-103-early-hints" tabindex="-1">替代方案：103 Early Hints <a class="header-anchor" href="#替代方案-103-early-hints" aria-label="Permalink to &quot;替代方案：103 Early Hints&quot;">​</a></h2><p>RFC 8297 的 <a href="/Front2Full/manual/computer-programming/http11/status-line"><code>103</code> 状态码</a>完成了同样的目标，且没有上述缺陷：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HTTP/2 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">103</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Early Hints</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">link</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;/style.css&gt;; rel=preload; as=style</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">link</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;/app.js&gt;; rel=preload; as=script</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HTTP/2 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OK</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">content-type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> text/html</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>对比：</p><table tabindex="0"><thead><tr><th></th><th>服务端推送</th><th>103 Early Hints</th></tr></thead><tbody><tr><td>服务端发的是</td><td><strong>资源本身</strong></td><td><strong>资源的 URL 提示</strong></td></tr><tr><td>客户端有缓存时</td><td>带宽已浪费</td><td>客户端自行跳过，零浪费</td></tr><tr><td>抢占带宽</td><td>会</td><td>不会</td></tr><tr><td>客户端控制权</td><td>只能事后取消</td><td>完全自主决定要不要取</td></tr><tr><td>省下的 RTT</td><td>1 个完整 RTT</td><td>服务器思考时间那一段</td></tr><tr><td>现状</td><td><strong>已废弃</strong></td><td>浏览器与 CDN 广泛支持</td></tr></tbody></table><p>代价是省得少一点（仍需客户端发起请求），但<strong>永远不会负优化</strong>——工程上这个取舍显然更优。</p><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><ul><li>HTTP/2：<code>PUSH_PROMISE</code> 与 <code>ENABLE_PUSH</code> 在 RFC 9113 中仍有定义，但浏览器不再支持。<strong>新系统不应使用</strong>。</li><li>HTTP/3：RFC 9114 <strong>仍定义</strong>了 <code>PUSH_PROMISE</code> 帧、<code>MAX_PUSH_ID</code> 与 <code>CANCEL_PUSH</code>，处境相同——规范里在，实践中无人用。</li><li>服务端应把 <code>SETTINGS_ENABLE_PUSH</code> 视作恒为 0 来设计。</li></ul><p><strong>结论</strong>：把它当作一段值得了解的协议史。要优化关键资源加载，用 <code>103 Early Hints</code> + <code>preload</code>。</p><p>第 1 部分结束。下一篇进入 <a href="/Front2Full/manual/computer-programming/http2-3/h3-overview">HTTP/3 总览</a>。</p>`,36)])])}const g=s(r,[["render",i]]);export{u as __pageData,g as default};
